output.sparql:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?occupation(COUNT(*) AS ?count) WHERE {
  ?award wdt:P31 wd:Q13137019 ; wdt:P1545 wd:Q194014 ; wdt:P585 ?awardDate ; wdt:P166 ?winner .
  FILTER(?awardDate >= "2004-01-01" ^^ xsd:date)
  ?winner wdt:P31 wd:Q5 .
  {
    ?winner wdt:P22 ?parent .
    ?parent wdt:P106 ?occupation .
  } UNION {
    ?winner wdt:P25 ?parent .
    ?parent wdt:P106 ?occupation .
  }
}
GROUP BY ?occupation
ORDER BY DESC(?count)
LIMIT 5

